-- APPLIED by the owner in the Supabase SQL editor on 28 Nov 2026 (sent in chat as RUN_THIS_private_and_asia_schools.sql).
-- ONE FILE TO RUN (27 Nov 2026). Paste all of it into the Supabase SQL editor and press Run.
-- It does three things, in order:
--   1. Lets PRIVATE schools outside Ghana show on the site (schema change, owner approved by running this).
--   2. Adds schools and programmes in Japan, South Korea, China, plus private universities in the UK, Canada and Australia.
--   3. Refreshes the search views so the new schools appear.
-- Sources: official university pages (and the Embassy of Japan's 2025-2026 guide for Japanese English minimums and fees).
-- Safe to run twice: schools and programmes that already exist are skipped.
-- Replaces the earlier files step217, step218, step219 and step220 sent on 27 Nov. Do not run those.

-- step217: show PRIVATE schools outside Ghana (owner request, 27 Nov 2026)
--
-- Why: three objects only show schools whose type is Public (or empty):
--   program_countries(), search_schools() and the materialized view program_groups.
-- A private school (Waseda, Keio, Yonsei, Ivy League...) would be loaded but never appear on the site.
-- New rule: Public or empty type everywhere, plus Private schools outside Ghana. Ghana stays public only.
--
-- This is a SCHEMA change (needs the owner's yes). Run it in the Supabase SQL editor.
-- program_groups has two materialized views built on it (program_group_counts, program_field_counts),
-- so all three are dropped and rebuilt with the same columns, indexes and grants as on 27 Nov 2026.
-- Only the WHERE line of program_groups changes. Search pages may be empty for the few seconds the rebuild takes.

begin;

-- 1. Country list
create or replace function public.program_countries(p_scope text default 'intl'::text)
 returns table(country text, n bigint)
 language sql
 stable security definer
 set search_path to 'public'
as $function$
  select s.country, count(*) n from schools s
  where (s.type is null or lower(s.type) = 'public' or (lower(s.type) = 'private' and lower(s.country) <> 'ghana'))
    and (case lower(p_scope) when 'local' then lower(s.country) = 'ghana' when 'intl' then lower(s.country) <> 'ghana' else true end)
    and exists (select 1 from programs p where p.school_id = s.id)
  group by s.country order by s.country;
$function$;

-- 2. Programme search view and the two views built on it
drop materialized view if exists public.program_field_counts;
drop materialized view if exists public.program_group_counts;
drop materialized view if exists public.program_groups;

create materialized view public.program_groups as
 SELECT (array_agg(p.id ORDER BY p.mode))[1] AS id,
    p.school_id,
    p.name,
    p.level,
    max(p.field) AS field,
    (count(*))::integer AS variants,
    array_agg(DISTINCT p.mode) AS modes,
    max(s.name) AS school_name,
    max(s.city) AS school_city,
    max(s.country) AS school_country,
    max(s.logo_url) AS school_logo,
    (lower(max(s.country)) = 'ghana'::text) AS is_local,
    lower(((((p.name || ' '::text) || COALESCE(max(p.field), ''::text)) || ' '::text) || max(s.name))) AS search
   FROM (programs p
     JOIN schools s ON ((s.id = p.school_id)))
  WHERE (((s.type IS NULL) OR (lower(s.type) = 'public'::text)
          OR (lower(s.type) = 'private'::text AND lower(s.country) <> 'ghana'::text))
         AND (lower(s.name) <> 'public nursing and midwifery training colleges (ministry of health)'::text))
  GROUP BY p.school_id, p.name, p.level;

CREATE UNIQUE INDEX program_groups_id_idx ON public.program_groups USING btree (id);
CREATE INDEX program_groups_school_idx ON public.program_groups USING btree (school_id);
CREATE INDEX program_groups_sort_idx ON public.program_groups USING btree (is_local, name, school_name);
CREATE INDEX program_groups_search_idx ON public.program_groups USING gin (search extensions.gin_trgm_ops);
CREATE INDEX program_groups_filter_idx ON public.program_groups USING btree (is_local, lower(school_country), lower(COALESCE(level, 'Undergraduate'::text)));
CREATE INDEX program_groups_field_idx ON public.program_groups USING btree (is_local, lower(COALESCE(field, ''::text)), name, school_name);

create materialized view public.program_group_counts as
 SELECT is_local,
    lower(school_country) AS country,
    lower(COALESCE(level, 'Undergraduate'::text)) AS level,
    count(*) AS n
   FROM program_groups
  GROUP BY is_local, (lower(school_country)), (lower(COALESCE(level, 'Undergraduate'::text)));

create materialized view public.program_field_counts as
 SELECT is_local,
    lower(COALESCE(school_country, ''::text)) AS country,
    lower(COALESCE(level, 'Undergraduate'::text)) AS level,
    COALESCE(field, ''::text) AS field,
    count(*) AS n
   FROM program_groups
  GROUP BY is_local, (lower(COALESCE(school_country, ''::text))), (lower(COALESCE(level, 'Undergraduate'::text))), COALESCE(field, ''::text);

CREATE UNIQUE INDEX program_field_counts_key ON public.program_field_counts USING btree (is_local, country, level, field);

-- Same access as before: program_groups and program_group_counts are not exposed to the API.
revoke all on public.program_groups from anon, authenticated;
revoke all on public.program_group_counts from anon, authenticated;
grant all on public.program_groups, public.program_group_counts, public.program_field_counts to service_role;
grant all on public.program_field_counts to anon, authenticated;

commit;

-- 3. School search: change the one WHERE line.
--    Done with a text replace on the live definition so nothing else in this long function changes.
do $$
declare d text;
begin
  d := pg_get_functiondef('public.search_schools'::regproc);
  if position($x$where (s.type is null or lower(s.type) = 'public')$x$ in d) = 0 then
    raise exception 'search_schools filter line not found; stop and check';
  end if;
  d := replace(d, $x$where (s.type is null or lower(s.type) = 'public')$x$,
                  $x$where (s.type is null or lower(s.type) = 'public' or (lower(s.type) = 'private' and lower(s.country) <> 'ghana'))$x$);
  execute d;
end $$;





