select 'Ulsan National Institute of Science and Technology (UNIST)','South Korea','Public','University','Ulsan','https://www.unist.ac.kr/',false,false,'{"ug": "UNIST teaches all courses in English. About 40 international undergraduates are admitted a year, entering in the fall; applicants choose Engineering or Business and declare a major at the end of the first year. For fall 2026 entry, online applications ran from 8 December 2025 to 23 January 2026 (16:00 Korea time). An official English test report (TOEFL, IELTS, TEPS or TOEIC, taken within 2 years) is required, but no minimum score is stated; native speakers from the US, Canada, UK, Australia, New Zealand and Ireland are exempt. The application fee is KRW 50,000.", "sources": ["https://admu-intl.unist.ac.kr/"]}'::jsonb,'https://admu-intl.unist.ac.kr/',date '2026-11-27'
