) v(country,sname,pname,field,yrs,fee,cur,ielts,toefl,duo,note,src)
join public.schools sc on sc.name=v.sname and sc.country=v.country
where not exists (select 1 from public.programs p where p.school_id=sc.id and p.name=v.pname);

commit;

-- ===== 3. Refresh search views =====
refresh materialized view public.program_groups;
refresh materialized view public.program_group_counts;
refresh materialized view public.program_field_counts;
analyze public.program_groups;

-- Check: new countries and counts
select s.country, s.type, count(distinct s.id) schools, count(p.id) programmes
from public.schools s left join public.programs p on p.school_id=s.id
where s.admission_checked = date '2026-11-27' group by 1,2 order by 1,2;
